import{_ as t,o as l,a as n,b as a}from"./app.DKoEZOcr.js";const i="/ascendc.github.io/pr/5487/assets/kernel_call.DZlGIUJa.png",g=JSON.parse('{"title":"","description":"","frontmatter":{"breadcrumbs":[{"text":"Ascend C算子开发指南","link":"/guide/getting_started/ascend_c_overview_and_learning_path"},{"text":"编程指南","link":"/guide/programming_guide/document_structure"},{"text":"编程模型","link":"/guide/programming_guide/programming_model/programming_model"},{"text":"AI Core SIMD编程","link":"/guide/programming_guide/programming_model/ai_core_simd_programming/ai_core_simd_programming"},{"text":"核函数（Kernel）","link":"/guide/programming_guide/programming_model/ai_core_simd_programming/kernel_function"}]},"headers":[],"relativePath":"guide/programming_guide/programming_model/ai_core_simd_programming/kernel_function.md","filePath":"guide/programming_guide/programming_model/ai_core_simd_programming/kernel_function.md","outlineHeaders":[{"level":2,"title":"核函数（Kernel）的定义","slug":"核函数（Kernel）的定义","link":"#核函数（Kernel）的定义"},{"level":2,"title":"核函数（Kernel）的调用","slug":"核函数（Kernel）的调用","link":"#核函数（Kernel）的调用"},{"level":2,"title":"Blocks索引内置变量","slug":"Blocks索引内置变量","link":"#Blocks索引内置变量"}],"lastUpdated":1787050286000}'),o={name:"guide/programming_guide/programming_model/ai_core_simd_programming/kernel_function.md"};function r(_,e,c,s,d,p){return l(),n("div",null,[...e[0]||(e[0]=[a(`<div><article class="markdown-body"><h1>核函数（Kernel）<span id="ZH-CN_TOPIC_0000001564710756"></span></h1><p>核函数（Kernel）是在设备侧并行执行的C/C++函数。它由主机端代码调用，调用时被实例化为多份并行副本，分别调度到多个AI Core上运行（每个AI Core被抽象为一个Block）。这些Block利用AI Core的计算能力，协同完成某一算子的计算。</p><h2 id="核函数（Kernel）的定义">核函数（Kernel）的定义<span id="zh-cn_topic_0000001447989210_section1915102519220"></span><a class="header-anchor" href="#核函数（Kernel）的定义">​</a></h2><p>定义核函数（Kernel）时需要遵循以下规则。</p><ul><li><p><strong>使用函数类型限定符和函数执行空间限定符</strong></p><p>除了需要按照C/C++函数声明的方式定义核函数（Kernel）之外，还要为核函数（Kernel）加上额外的函数类型限定符。</p><p>必须使用__global__函数类型限定符来标识它是一个核函数（Kernel），可以被&lt;&lt;&lt;...&gt;&gt;&gt;调用。同时，需要根据算子实际执行的硬件单元，选择以下一种函数执行空间限定符，详情参考<a href="../../language_extension/simd_builtin_keywords.html#section1074418132518">函数执行空间限定符</a>：</p><ul><li>__aicore__：标识该核函数（Kernel）在设备端AI核上执行，不区分具体核类型（通常用于<a href="../../advanced_programming/hardware_implementation/basic_architecture.html#section1574769433">耦合模式</a>）。</li><li>__vector__：标识该核函数（Kernel）在设备端Vector核上执行，适用于仅包含Vector计算的算子。</li><li>__cube__：标识该核函数（Kernel）在设备端Cube核上执行，适用于仅包含Cube计算的算子。</li><li>__mix__：标识该核函数（Kernel）同时在Cube核和Vector核上执行，适用于包含Vector和Cube融合计算的算子。</li></ul></li><li><p><strong>使用变量类型限定符</strong></p><p>指针入参变量需要增加变量类型限定符__gm__，表明该指针变量指向Global Memory上某处内存地址。</p></li><li><p><strong>其他规则</strong><span id="zh-cn_topic_0000001447989210_li94421027152419"></span></p><ol><li>规则：核函数（Kernel）必须具有void返回类型。</li><li>规则：核函数（Kernel）参数列表需遵循<a href="../../../technical_appendix/cpp_standard_support/syntax_restrictions/functions.html#section_kernel_function_argument_list_constraint">函数参数列表限制</a>。</li></ol></li><li><p>代码示例如下：</p><div class="code-block"><div class="code-header"><span class="lang-label">Text</span><button class="copy-btn" title="复制代码"><svg width="16" height="16" viewBox="0 0 16 16"><path d="M0 6.75C0 5.784.784 5 1.75 5h1.5a.75.75 0 0 1 0 1.5h-1.5a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-1.5a.75.75 0 0 1 1.5 0v1.5A1.75 1.75 0 0 1 9.25 16h-7.5A1.75 1.75 0 0 1 0 14.25Z"></path><path d="M5 1.75C5 .784 5.784 0 6.75 0h7.5C15.216 0 16 .784 16 1.75v7.5A1.75 1.75 0 0 1 14.25 11h-7.5A1.75 1.75 0 0 1 5 9.25Zm1.75-.25a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-7.5a.25.25 0 0 0-.25-.25Z"></path></svg></button></div><pre class="highlight"><code>// Use the __global__ and __vector__ qualifiers to define kernel functions.
__global__ __vector__ void add_kernel(__gm__ float* x, __gm__ float* y, __gm__ float* z)
{
    ...
}

// Template-based definition of kernel functions is supported. An example of such a definition is provided below; it includes one type template parameter.
template&lt;typename T&gt;
__global__ __vector__ void add_kernel(__gm__ T* x, __gm__ T* y, __gm__ T* z)
{
    ...
}
</code></pre></div></li></ul><h2 id="核函数（Kernel）的调用">核函数（Kernel）的调用<a class="header-anchor" href="#核函数（Kernel）的调用">​</a></h2><p>在Ascend C算子编程中，根据代码执行空间的不同，函数被严格划分为三类。它们之间的调用关系遵循如下规则：</p><ul><li>Host侧执行函数：运行于主机端（CPU）。除了支持标准C/C++语义下的同类函数互调外，其核心作用是作为计算任务的发起者，通过内核调用符&lt;&lt;&lt;...&gt;&gt;&gt;下发执行配置，跨界调用设备侧的核函数（Kernel）。</li><li>核函数（Kernel）：运行于设备端（NPU），是Host侧任务下发的执行入口。核函数（Kernel）在组织并行计算逻辑时，可以向下调用其他的Device侧执行函数。</li><li>Device侧执行函数：运行于设备端（NPU）的普通函数（除核函数（Kernel）外）。此类函数主要用于封装和复用底层计算逻辑，其调用权限被严格限制在设备侧内部，仅支持被核函数（Kernel）或同类的Device侧执行函数调用。</li></ul><p><strong>图1</strong> 核函数（Kernel）、host侧执行函数、device侧执行函数调用关系<span id="fig321723224511"></span><br><img src="`+i+`" alt title="核函数（Kernel）-host侧执行函数-device侧执行函数调用关系"></p><p>Host侧通过内核调用符&lt;&lt;&lt;...&gt;&gt;&gt;的语法形式调用核函数（Kernel），如下所示：</p><div class="code-block"><div class="code-header"><span class="lang-label">Text</span><button class="copy-btn" title="复制代码"><svg width="16" height="16" viewBox="0 0 16 16"><path d="M0 6.75C0 5.784.784 5 1.75 5h1.5a.75.75 0 0 1 0 1.5h-1.5a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-1.5a.75.75 0 0 1 1.5 0v1.5A1.75 1.75 0 0 1 9.25 16h-7.5A1.75 1.75 0 0 1 0 14.25Z"></path><path d="M5 1.75C5 .784 5.784 0 6.75 0h7.5C15.216 0 16 .784 16 1.75v7.5A1.75 1.75 0 0 1 14.25 11h-7.5A1.75 1.75 0 0 1 5 9.25Zm1.75-.25a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-7.5a.25.25 0 0 0-.25-.25Z"></path></svg></button></div><pre class="highlight"><code>kernel_name&lt;&lt;&lt;numBlocks, dynUBufSize, stream&gt;&gt;&gt;(argument list);
</code></pre></div><p><code>&lt;&lt;&lt;...&gt;&gt;&gt;</code>内的参数为核函数（Kernel）的执行配置，由3个参数决定，详细用法请参考<a href="../../language_extension/simd_builtin_keywords.html#%E6%A0%B8%E5%87%BD%E6%95%B0%E9%85%8D%E7%BD%AE">核函数（Kernel）配置</a>：</p><ul><li>numBlocks：规定了核函数（Kernel）将会在几个核上执行，对于不同的硬件架构和算子类型，numBlocks的设置规则有一些区别，详见<a href="../../language_extension/simd_builtin_keywords.html#%E6%A0%B8%E5%87%BD%E6%95%B0%E9%85%8D%E7%BD%AE">核函数（Kernel）配置</a>。每个执行该核函数（Kernel）的核会被分配一个逻辑ID，即block_idx，可以在核函数（Kernel）的实现中使用内置变量<a href="../../language_extension/simd_builtin_keywords.html#%E5%86%85%E7%BD%AE%E5%8F%98%E9%87%8F">block_idx</a>获取。需要注意的是，在使用<code>__mix__</code>函数执行空间限定符的场景下，处在同一核上的Vector Core的block_idx取值相同，详细说明和示例请参考<a href="../../language_extension/simd_builtin_keywords.html#%E5%86%85%E7%BD%AE%E5%8F%98%E9%87%8F">内置变量</a>；</li><li>dynUBufSize：Dynamic Unified Buffer（UB） Size，是配置UB动态内存分配的空间的大小（仅限UB，不包括L1 Buffer等），单位为bytes，默认设置为0；</li><li>stream：类型为aclrtStream，stream用于维护一些异步操作的执行顺序，确保按照应用程序中的代码调用顺序在device上执行，默认设置为nullptr。stream创建等管理接口请参考<a href="https://hiascend.com/document/redirect/CannCommunityRuntimeApi">《Runtime运行时API》</a>。</li></ul><p>如下名为add_custom的核函数（Kernel），实现两个矢量的相加，调用示例如下：</p><div class="code-block"><div class="code-header"><span class="lang-label">Text</span><button class="copy-btn" title="复制代码"><svg width="16" height="16" viewBox="0 0 16 16"><path d="M0 6.75C0 5.784.784 5 1.75 5h1.5a.75.75 0 0 1 0 1.5h-1.5a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-1.5a.75.75 0 0 1 1.5 0v1.5A1.75 1.75 0 0 1 9.25 16h-7.5A1.75 1.75 0 0 1 0 14.25Z"></path><path d="M5 1.75C5 .784 5.784 0 6.75 0h7.5C15.216 0 16 .784 16 1.75v7.5A1.75 1.75 0 0 1 14.25 11h-7.5A1.75 1.75 0 0 1 5 9.25Zm1.75-.25a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-7.5a.25.25 0 0 0-.25-.25Z"></path></svg></button></div><pre class="highlight"><code>// numBlocks is set to 8: Indicates that the add_kernel function is invoked on 8 cores. Each core will execute the kernel independently and in parallel.
// dynUBufSize is set to 0: Indicates that no dynamic memory space is allocated for the UB. The argument list for the kernel is x, y, z.
add_kernel&lt;&lt;&lt;8, 0, stream&gt;&gt;&gt;(x, y, z);

// The invocation format for a template kernel function is as follows:
// 1. Process Float32 vector addition.
add_kernel&lt;float&gt;&lt;&lt;&lt;8, 0, stream&gt;&gt;&gt;(x_float, y_float, z_float);
// 2. Simply change the template parameter to int32_t to perform integer computation.
add_kernel&lt;int32_t&gt;&lt;&lt;&lt;8, 0, stream&gt;&gt;&gt;(x_int, y_int, z_int);
</code></pre></div><p>核函数（Kernel）的调用是异步的，核函数（Kernel）的调用结束后，控制权立刻返回给主机端，可以调用以下<strong>aclrtSynchronizeStream</strong>函数来强制主机端程序等待所有核函数（Kernel）执行完毕。</p><div class="code-block"><div class="code-header"><span class="lang-label">Text</span><button class="copy-btn" title="复制代码"><svg width="16" height="16" viewBox="0 0 16 16"><path d="M0 6.75C0 5.784.784 5 1.75 5h1.5a.75.75 0 0 1 0 1.5h-1.5a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-1.5a.75.75 0 0 1 1.5 0v1.5A1.75 1.75 0 0 1 9.25 16h-7.5A1.75 1.75 0 0 1 0 14.25Z"></path><path d="M5 1.75C5 .784 5.784 0 6.75 0h7.5C15.216 0 16 .784 16 1.75v7.5A1.75 1.75 0 0 1 14.25 11h-7.5A1.75 1.75 0 0 1 5 9.25Zm1.75-.25a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-7.5a.25.25 0 0 0-.25-.25Z"></path></svg></button></div><pre class="highlight"><code>aclError aclrtSynchronizeStream(aclrtStream stream);
</code></pre></div><p>aclrtSynchronizeStream的具体用法参考<a href="https://hiascend.com/document/redirect/CannCommunityRuntimeApi">《Runtime运行时API》</a>。</p><h2 id="Blocks索引内置变量">Blocks索引内置变量<a class="header-anchor" href="#Blocks索引内置变量">​</a></h2><p>在通过 &lt;&lt;&lt;numBlocks, ...&gt;&gt;&gt; 启动多核并行计算后，多个AI Core会同时执行同一份核函数（Kernel）代码。为了避免多个核重复处理同一块数据，我们需要在代码中对全局数据进行切分。</p><p>Ascend C提供了内置变量block_idx和block_num，帮助每个核精准定位自己需要处理的数据切片：</p><ul><li>block_num：获取当前核函数（Kernel）被分配的逻辑核总数（其值等于内核调用时配置的numBlocks）。</li><li>block_idx：获取当前执行代码的逻辑核ID，取值范围为[0, block_num - 1]。</li></ul><p>在Mix场景（使用<code>__mix__</code>函数执行空间限定符）下，Vector核（AIV）还需要通过sub_block_idx来确定在组合内的位置：</p><ul><li>sub_block_num：获取当前组合内Vector核的数量（即每个组合中AIV的个数）。</li><li>sub_block_idx：获取当前Vector核在组合内的索引，取值范围为[0, sub_block_num - 1]。</li></ul><p>在Mix场景中，AIV核的完整逻辑位置由block_idx和sub_block_idx共同确定：<code>logic_idx = block_idx * sub_block_num + sub_block_idx</code>。开发者应使用<a href="../../../../api/SIMD-API/basic_api/tool_interface/system_resources_and_variables/GetBlockIdx.html">GetBlockIdx</a>和<a href="../../../../api/SIMD-API/basic_api/tool_interface/system_resources_and_variables/GetSubBlockIdx_ISASI.html">GetSubBlockIdx</a> API组合获取逻辑位置，而非直接使用内置变量（更多说明参见<a href="../../language_extension/simd_builtin_keywords.html#%E5%86%85%E7%BD%AE%E5%8F%98%E9%87%8F">内置变量</a>中的注意事项）。</p><p>以下示例展示了如何利用block_idx和block_num，将总长度为TOTAL_LENGTH的一维数据均匀分配给多个核进行处理：</p><div class="code-block"><div class="code-header"><span class="lang-label">Text</span><button class="copy-btn" title="复制代码"><svg width="16" height="16" viewBox="0 0 16 16"><path d="M0 6.75C0 5.784.784 5 1.75 5h1.5a.75.75 0 0 1 0 1.5h-1.5a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-1.5a.75.75 0 0 1 1.5 0v1.5A1.75 1.75 0 0 1 9.25 16h-7.5A1.75 1.75 0 0 1 0 14.25Z"></path><path d="M5 1.75C5 .784 5.784 0 6.75 0h7.5C15.216 0 16 .784 16 1.75v7.5A1.75 1.75 0 0 1 14.25 11h-7.5A1.75 1.75 0 0 1 5 9.25Zm1.75-.25a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-7.5a.25.25 0 0 0-.25-.25Z"></path></svg></button></div><pre class="highlight"><code>// Assume the total amount of data to be processed is predefined in a macro.
constexpr uint32_t TOTAL_LENGTH = 8192;

__global__ __vector__ void add_kernel(__gm__ float* x, __gm__ float* y, __gm__ float* z)
{
    // 1. Get the logical ID of the current core and the total number of logical cores participating in the computation.
    uint32_t core_idx = block_idx;
    uint32_t core_num = block_num;

    // 2. Calculate the amount of data to be processed by the current core.
    // Assume TOTAL_LENGTH is perfectly divisible by core_num.
    uint32_t data_per_core = TOTAL_LENGTH / core_num;

    // 3. Calculate the data offset of the current core in Global Memory.
    uint32_t offset = core_idx * data_per_core;

    // 4. Offset the global pointers to obtain the addresses of the data slices belonging to the current core.
    __gm__ float* x_local = x + offset;
    __gm__ float* y_local = y + offset;
    __gm__ float* z_local = z + offset;

    // 5. Subsequent logic: Each core independently processes its own data slice (e.g., move to UB, vector addition, write back, etc.).
    // op.Init(x_local, y_local, z_local, data_per_core);
    // op.Process();
}
</code></pre></div><p>假设我们通过add_kernel&lt;&lt;&lt;8, 0, stream&gt;&gt;&gt;(x, y, z);启动了上述核函数（Kernel）（即block_num = 8）。</p><ul><li>当block_idx = 0的核执行时，它的offset = 0，将负责处理全局数组中索引从0到1023的数据。</li><li>当block_idx = 1的核执行时，它的offset = 1024，将负责处理全局数组中索引从1024到2047的数据。</li><li>以此类推，8个核完全并行且互不干扰地完成了8192个数据的计算。通过这种分片机制，block_idx实现了软硬件之间的一一映射。</li></ul></article></div>`,1)])])}const h=t(o,[["render",r]]);export{g as __pageData,h as default};
